#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <tuple>
#include <climits>
using namespace std;

using ll = long long;
const ll INF = 1000000009;

struct Edge {
    int u, v, f, c;
    Edge(int u, int v, int f, int c) : u(u), v(v), f(f), c(c) {}
};

int source, sink;
vector<vector<int>> adj;
vector<Edge> edgeList;

void connect(int u, int v, int cap) {
    adj[u].push_back(edgeList.size());
    edgeList.emplace_back(u, v, 0, cap);
    adj[v].push_back(edgeList.size());
    edgeList.emplace_back(v, u, 0, 0);
}

int ptr[1001], level[1001];

bool buildLevelGraph() {
    memset(level, -1, sizeof(level));
    level[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            auto& e = edgeList[id];
            if (level[e.v] == -1 && e.f < e.c) {
                level[e.v] = level[u] + 1;
                q.push(e.v);
                if (e.v == sink) return true;
            }
        }
    }
    return false;
}

ll pushFlow(int u, ll flow) {
    if (u == sink || flow == 0) return flow;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        int id = adj[u][i];
        auto& e = edgeList[id];
        if (level[e.v] != level[u] + 1) continue;
        ll pushed = pushFlow(e.v, min(flow, (ll)e.c - e.f));
        if (pushed) {
            e.f += pushed;
            edgeList[id ^ 1].f -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll computeMaxFlow() {
    ll total = 0;
    while (buildLevelGraph()) {
        memset(ptr, 0, sizeof(ptr));
        ll pushed;
        while ((pushed = pushFlow(source, INF)) > 0)
            total += pushed;
    }
    return total;
}

string scientists[101], reactors[101];
bool pathExists[10][10][10][10];
int visitedCells[101][101];
int disableTime[10][10];
int rows, cols;

bool inside(int r, int c) {
    return r >= 0 && c >= 0 && r < rows && c < cols;
}

int cellId(int r, int c) {
    return 1 + cols * r + c;
}

int main() {
    ios::sync_with_stdio(false);
    int T;
    cin >> rows >> T;
    ++T;
    cols = rows;
    sink = cols * cols * 2 + 1;
    source = 0;
    adj.resize(cols * cols * 2 + 2);
    queue<pair<int, int>> q;
    for (int i = 0; i < rows; ++i) cin >> scientists[i];
    for (int i = 0; i < rows; ++i) {
        cin >> reactors[i];
        for (int j = 0; j < cols; ++j) {
            disableTime[i][j] = INF;
            if (reactors[i][j] == 'Z') {
                q.push({i, j});
                disableTime[i][j] = 1;
            }
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int di = -1; di <= 1; ++di)
            for (int dj = -1; dj <= 1; ++dj)
                if (abs(di) + abs(dj) == 1) {
                    int nx = x + di, ny = y + dj;
                    if (inside(nx, ny) && disableTime[nx][ny] == INF && scientists[nx][ny] != 'Y') {
                        disableTime[nx][ny] = disableTime[x][y] + 1;
                        q.push({nx, ny});
                    }
                }
    }
    for (int x = 0; x < rows; ++x)
        for (int y = 0; y < cols; ++y) {
            if (scientists[x][y] >= '1' && scientists[x][y] <= '9')
                connect(source, cellId(x, y), scientists[x][y] - '0');
            if (reactors[x][y] >= '1' && reactors[x][y] <= '9')
                connect(rows * rows + cellId(x, y), sink, reactors[x][y] - '0');
            for (int X = 0; X < rows; ++X)
                for (int Y = 0; Y < cols; ++Y) {
                    if (scientists[x][y] == 'Y' || scientists[x][y] == 'Z' ||
                        reactors[X][Y] == 'Y' || reactors[X][Y] == 'Z')
                        continue;
                    memset(visitedCells, 0, sizeof(visitedCells));
                    queue<tuple<int, int, int>> bq;
                    bq.emplace(x, y, 1);
                    visitedCells[x][y] = 1;
                    while (!bq.empty()) {
                        auto [cx, cy, t] = bq.front(); bq.pop();
                        if (cx == X && cy == Y) {
                            visitedCells[cx][cy] = 1;
                            break;
                        }
                        if (t >= disableTime[cx][cy] || t >= T) continue;
                        for (int di = -1; di <= 1; ++di)
                            for (int dj = -1; dj <= 1; ++dj)
                                if (abs(di) + abs(dj) == 1) {
                                    int nx = cx + di, ny = cy + dj;
                                    if (inside(nx, ny) && !visitedCells[nx][ny] &&
                                        scientists[nx][ny] != 'Y' && scientists[nx][ny] != 'Z' &&
                                        t + 1 <= disableTime[nx][ny]) {
                                        visitedCells[nx][ny] = 1;
                                        bq.emplace(nx, ny, t + 1);
                                    }
                                }
                    }
                    if (visitedCells[X][Y])
                        connect(cellId(x, y), rows * rows + cellId(X, Y), INF);
                }
        }
    cout << computeMaxFlow() << '\n';
}
